content.query:
let snapshot = traces
| where isnotempty(customDimensions.UsageUserId)
| extend SnapshotAt = todatetime(customDimensions.UsageSnapshotAt), UserId = toint(customDimensions.UsageUserId),
    SignedUp = todatetime(customDimensions.UserCreatedAt), PracticeResults = toint(customDimensions.PracticeResultCount);
let lastSnapshot = toscalar(snapshot | summarize max(SnapshotAt));
let people = snapshot | where SnapshotAt == lastSnapshot | summarize arg_max(timestamp, *) by UserId
| extend LifetimeDays = max_of(1.0, (lastSnapshot - SignedUp) / 1d)
| extend LifetimeMonths = max_of(1.0, LifetimeDays / 30.4);
let active = requests | where timestamp > ago(30d) and isnotempty(user_AuthenticatedId);
let practice = active
| where name startswith 'POST' and resultCode == '200'
| where tostring(parse_url(url).Path) matches regex @'^/api/flashcards/\d+/practice-results$';
let monthCount = coalesce(toscalar(practice | summarize sum(itemCount)), tolong(0));
let dayCount = coalesce(toscalar(practice | where timestamp > ago(1d) | summarize sum(itemCount)), tolong(0));
let mau = toscalar(active | summarize dcount(user_AuthenticatedId));
let dau = toscalar(active | where timestamp > ago(1d) | summarize dcount(user_AuthenticatedId));
union
    (print Order = 0, Metric = 'Practice results (past day)', Value = tostring(dayCount)),
    (print Order = 1, Metric = 'Practice results (past 30 days)', Value = tostring(monthCount)),
    (print Order = 2, Metric = 'Per active user (past day)', Value = tostring(iff(dau == 0, 0.0, round(1.0 * dayCount / dau, 1)))),
    (print Order = 3, Metric = 'Per active user (past 30 days)', Value = tostring(iff(mau == 0, 0.0, round(1.0 * monthCount / mau, 1)))),
    (print Order = 4, Metric = 'Per user (all time)', Value = tostring(toscalar(people | summarize round(avg(PracticeResults), 1)))),
    (print Order = 5, Metric = 'Per user per month (lifetime average)',
        Value = tostring(toscalar(people | summarize round(avg(PracticeResults / LifetimeMonths), 1)))),
    (print Order = 6, Metric = 'Per user per day (lifetime average)',
        Value = tostring(toscalar(people | summarize round(avg(PracticeResults / LifetimeDays), 1))))
| order by Order asc
| extend Value = iff(isempty(Value) or Value == 'NaN', 'No snapshot yet', Value)
| project Metric, Value
